void __fastcall D2MEM_CopyRows(char * pCharSelComp, uint32_t * pSrc, int32_t nDstStride, int32_t nSrcStride, int32_t nRows, uint32_t nBytesPerRow) {
    do {
      uint32_t nRemainder;
      nRemainder = nBytesPerRow & 3;
      if (nRemainder) {
        switch (nRemainder) {
          case 1:
            {
              *pCharSelComp = *(char*)pSrc;
              pCharSelComp++;
              pSrc = (uint32_t*)((int)pSrc + 1);
              break;
            }
          case 2:
            {
              *pCharSelComp = *(char*)pSrc;
              pCharSelComp[1] = *(char*)((int)pSrc + 1);
              pCharSelComp += 2;
              pSrc = (uint32_t*)((int)pSrc + 2);
              break;
            }
          default:
            {
              *pCharSelComp = *(char*)pSrc;
              pCharSelComp[1] = *(char*)((int)pSrc + 1);
              pCharSelComp[2] = *(char*)((int)pSrc + 2);
              pCharSelComp += 3;
              pSrc = (uint32_t*)((int)pSrc + 3);
            }
        }
      }

      for (nRemainder = nBytesPerRow >> 2; nRemainder; nRemainder--) {
        *(uint32_t*)pCharSelComp = *pSrc;
        pSrc = (uint32_t*)((int)pSrc + 4);
        pCharSelComp += 4;
      }

      pSrc = (uint32_t*)((int)pSrc + (nSrcStride - nBytesPerRow));
      pCharSelComp += nDstStride - nBytesPerRow;
      nRows--;
    } while (nRows);
}

uint32_t __fastcall D2MEM_CompareBytes(int * pBuf1, int * pBuf2, uint32_t nByteCount) {
    uint32_t nRemainder = nByteCount & 3;
    if (nRemainder) {
      switch (nRemainder) {
        case 1:
          {
            if ((char)*pBuf2 != (char)*pBuf1) {
              return 0;
            }

            pBuf1 = (int*)((int)pBuf1 + 1);
            pBuf2 = (int*)((int)pBuf2 + 1);
            break;
          }
        case 2:
          {
            if ((char)*pBuf2 != (char)*pBuf1) {
              return 0;
            }
            if (*(char*)((int)pBuf2 + 1) != *(char*)((int)pBuf1 + 1)) {
              return 0;
            }

            pBuf1 = (int*)((int)pBuf1 + 2);
            pBuf2 = (int*)((int)pBuf2 + 2);
            break;
          }
        default:
          {
            if ((char)*pBuf2 != (char)*pBuf1) {
              return 0;
            }
            if (*(char*)((int)pBuf2 + 1) != *(char*)((int)pBuf1 + 1)) {
              return 0;
            }
            if (*(char*)((int)pBuf2 + 2) != *(char*)((int)pBuf1 + 2)) {
              return 0;
            }

            pBuf1 = (int*)((int)pBuf1 + 3);
            pBuf2 = (int*)((int)pBuf2 + 3);
          }
      }
    }

    nRemainder = nByteCount >> 2;
    bool bEqual = !nRemainder;
    do {
      if (!nRemainder) {
        break;
      }

      nRemainder--;
      bEqual = *pBuf2 == *pBuf1;
      pBuf2++;
      pBuf1++;
    } while (bEqual);

    if (bEqual) {
      return 1;
    }

    return 0;
}

int32_t D2MEM_FindLowestSetBit(uint32_t dwMask) {
    if (!dwMask) {
      return 0;
    }

    int nBitPos = 0;
    if (dwMask) {
      for (; !(dwMask >> nBitPos & 1); nBitPos++) {}
    }

    return nBitPos + 1;
}

