// @evidence MOV EAX,0x72fa18 / NOT EAX / MOV [0x72fa1c],EAX - writes the
// end-of-list terminator into gFaultHandlerList.head.pNext. The .data image
// already carries head.pPrevLink = &gFaultHandlerList.head (0x0072fa18); only
// the ~ptr terminator needs a dynamic initializer.
// @caveat the decompiler CONSTANT-FOLDS ~0x0072fa18 into 0xff8d05e7 and loses
// the self-reference. The emitted C++ must read
//   gFaultHandlerList.head.pNext = (void *)~(uintptr_t)&gFaultHandlerList.head;
// A rebuilt image that stores the literal 0xff8d05e7 makes
// LINKEDLIST_GetNodePointer return ~0xff8d05e7 == 0x0072fa18, i.e. a write to
// the ORIGINAL image address. Address-relative, not a constant.
void StaticInit_gFaultHandlerList() {
    gFaultHandlerList.head.pNext = ~(uintptr_t)((char*)&gFaultHandlerList + 4);
    atexit(StaticFini_gFaultHandlerList);
}

void StaticFini_gFaultHandlerList() {
    TSList_TMESSAGESOURCE_UnlinkAll(&gFaultHandlerList);
    TSLink_TMESSAGESOURCE_Unlink(&gFaultHandlerList.head);
}

